-- mesh.lua
-- Generated by eilmer-mesher. Edit the .emesh.json project, not this file.
--   lmr prep-grids -j mesh.lua      registers the grids for a simulation
--   lmr custom-script -j mesh.lua   writes preview/blk-NNNN.vtk for the GUI
if config then config.dimensions = 2 end

-- points
p000 = Vector3:new{x=0.3, y=0.75}
p001 = Vector3:new{x=0.8666666666666667, y=0.5}
p002 = Vector3:new{x=1.0, y=0.0}
p003 = Vector3:new{x=0.0, y=0.0}
p004 = Vector3:new{x=2.0, y=0.0}
p005 = Vector3:new{x=0.6, y=1.5}
p006 = Vector3:new{x=1.3, y=0.75}

-- paths
path_c6 = Line:new{p0=p000, p1=p001}
path_c4 = Line:new{p0=p002, p1=p001}
path_c1 = Line:new{p0=p003, p1=p004}
path_c3 = Line:new{p0=p005, p1=p003}
path_c5 = Line:new{p0=p006, p1=p001}
path_c2 = Line:new{p0=p004, p1=p005}

-- blocks
blocks = {}
-- block blk1
surf_blk1 = CoonsPatch:new{north=path_c6, east=path_c4, south=SubRangedPath:new{underlying_path=path_c1, t0=0.0, t1=0.5}, west=SubRangedPath:new{underlying_path=path_c3, t0=1.0, t1=0.5}}
grid_blk1 = StructuredGrid:new{psurface=surf_blk1, niv=12, njv=10, label="blk1"}
blocks[#blocks+1] = {grid=grid_blk1, tag="blk1", fsTag="initial", bcTags={}}

-- block blk2
surf_blk2 = CoonsPatch:new{north=ReversedPath:new{underlying_path=path_c5}, east=SubRangedPath:new{underlying_path=path_c2, t0=0.0, t1=0.5}, south=SubRangedPath:new{underlying_path=path_c1, t0=0.5, t1=1.0}, west=path_c4}
grid_blk2 = StructuredGrid:new{psurface=surf_blk2, niv=12, njv=10, label="blk2"}
blocks[#blocks+1] = {grid=grid_blk2, tag="blk2", fsTag="initial", bcTags={}}

-- block blk3
surf_blk3 = CoonsPatch:new{north=SubRangedPath:new{underlying_path=path_c2, t0=1.0, t1=0.5}, east=ReversedPath:new{underlying_path=path_c5}, south=path_c6, west=SubRangedPath:new{underlying_path=path_c3, t0=0.5, t1=0.0}}
grid_blk3 = StructuredGrid:new{psurface=surf_blk3, niv=12, njv=12, label="blk3"}
blocks[#blocks+1] = {grid=grid_blk3, tag="blk3", fsTag="initial", bcTags={}}

if registerFluidGrid then
   -- lmr prep-grids
   local ids = {}
   for i, b in ipairs(blocks) do
      ids[i] = registerFluidGrid{grid=b.grid, tag=b.tag, fsTag=b.fsTag, bcTags=b.bcTags}
   end
   -- Blocks are joined only across block split lines; a solid curve between
   -- two blocks stays a wall on both sides.
   connectGrids(ids[1], "east", ids[2], "west")
   connectGrids(ids[2], "north", ids[3], "east")
   connectGrids(ids[1], "north", ids[3], "south")
else
   -- lmr custom-script: preview output for the GUI
   os.execute("mkdir -p preview")
   for i, b in ipairs(blocks) do
      b.grid:write_to_vtk_file(string.format("preview/blk-%04d.vtk", i-1))
   end
end
